SELECT SUM(OP.PAYMENT_VALUE) AS BUSINESS_VOLUME
FROM ORDER_PAYMENTS OP
JOIN ORDERS O ON OP.ORDER_ID = O.ORDER_ID
WHERE O.ORDER_PURCHASE_TIMESTAMP >= (
    SELECT MAX(ORDER_PURCHASE_TIMESTAMP) FROM ORDERS
) - INTERVAL 90 DAY;

SELECT AVG(REVIEW_SCORE) AS AVG_REVIEW_SCORE
FROM (
    SELECT ORDER_ID, AVG(REVIEW_SCORE) AS REVIEW_SCORE
    FROM MARKETPLACE.ORDER_REVIEWS
    GROUP BY ORDER_ID
) AS DEDUPED_REVIEWS;

SELECT AVG(ORDER_REVIEW_SCORE) AS AVG_REVIEW_SCORE
FROM (
    SELECT ORDER_ID, AVG(REVIEW_SCORE) AS ORDER_REVIEW_SCORE
    FROM MARKETPLACE.ORDER_REVIEWS
    GROUP BY ORDER_ID
) AS PER_ORDER;

SELECT AVG(REVIEW_SCORE) AS AVERAGE_REVIEW_SCORE
FROM (
    SELECT ORDER_ID, AVG(REVIEW_SCORE) AS REVIEW_SCORE
    FROM MARKETPLACE.ORDER_REVIEWS
    GROUP BY ORDER_ID
) AS DEDUP_REVIEWS;
